  ('M4 x 0.7mm Zinc-Plated Socket Head Screw (5mm Length) - 25 Pack', '2800-0004-0005', null, 'goBILDA', null, true, 'https://www.gobilda.com/2800-series-zinc-plated-steel-socket-head-screw-m4-x-0-7mm-5mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/471/images/3240/2800-0004-0005__33058__22265.1701991831.386.513.jpg?c=1', 'HARDWARE / Screws / M4 Socket Head Screws', 'gobilda'),
  ('M4 x 0.7mm Zinc-Plated Socket Head Screw (6mm Length) — 25 Pack', '2800-0004-0006', null, 'goBILDA', null, true, 'https://www.gobilda.com/m4-x-0-7mm-zinc-plated-socket-head-screw-6mm-length/?sku=2800-0004-0006', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2218/images/12636/2800-0004-0006__57831__08375__94236__36336.1720539040.386.513.jpg?c=1', 'HARDWARE / Screws / M4 Socket Head Screws', 'gobilda'),
