  ('2804 Series Zinc-Plated Steel Low Profile Socket Head Screw (M4 x 0.7mm, 55mm Length) - 25 Pack', '2804-0004-0055', null, 'goBILDA', null, true, 'https://www.gobilda.com/2804-series-zinc-plated-steel-low-profile-socket-head-screw-m4-x-0-7mm-55mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/783/images/4440/2804-0004-0055__84987__14081.1701992196.386.513.jpg?c=1', 'HARDWARE / Screws / M4 Low Profile Socket Head Screws', 'gobilda'),
  ('2804 Series Zinc-Plated Steel Low Profile Socket Head Screw (M4 x 0.7mm, 60mm Length) - 25 Pack', '2804-0004-0060', null, 'goBILDA', null, true, 'https://www.gobilda.com/2804-series-zinc-plated-steel-low-profile-socket-head-screw-m4-x-0-7mm-60mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/785/images/4444/2804-0004-0060__58372__30848.1701992197.386.513.jpg?c=1', 'HARDWARE / Screws / M4 Low Profile Socket Head Screws', 'gobilda'),
  ('goRAIL® Nut (1 Hole) - 4 Pack', '2805-0004-0008', 'This product has been discontinued. It has been replaced by the Hurricane Nut (2805-0004-0108). goRAIL nuts are purpose-built to slide down the slot of 1109 Series goRAIL or 1118 Series Open goRAIL to provide an M4 threaded hole at any location you wish. The 8mm length allows them to stack next to one(4) another and remain on the 8mm grid pattern.', 'goBILDA', null, true, 'https://www.gobilda.com/gorail-nut-1-hole-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/505/images/3311/2805-0004-0008__67185__40881.1701991858.386.513.jpg?c=1', null, 'gobilda'),
  ('goRAIL® Nut (5 Hole) - 2 Pack', '2805-0004-0038', '5 Hole goRAIL nuts provide additional surface contact between the goRAIL and the nut for heavy duty applications. Using a nut with multiple holes makes alignment very simple as there''s no chance of it sliding down the slot as long as one(5) fastener is threaded into the nut.', 'goBILDA', null, true, 'https://www.gobilda.com/gorail-nut-5-hole-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/507/images/3318/2805-0004-0038__35332__37043.1701991860.386.513.jpg?c=1', 'STRUCTURE / goRAIL® / goRAIL® Accessories', 'gobilda'),
  ('Hurricane Nut for goRAIL® - 25 Pack', '2805-0004-0108', 'Hurricane Nuts are purpose-built to fit into the slot of 1109 Series goRAIL or 1118 Series Open goRAIL to provide an M4 threaded hole at any location you wish. The "hurricane" shape allows you to drop them in mid-slot without having to slide them in from the end of the goRAIL. The overall length allows them to stack next to one(6) another and remain on the 8mm grid pattern.', 'goBILDA', null, true, 'https://www.gobilda.com/hurricane-nut-for-gorail-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1375/images/6734/2805-0004-0108__68134__83447.1701992948.386.513.jpg?c=1', 'STRUCTURE / goRAIL® / goRAIL® Accessories', 'gobilda'),
  ('2806 Series Black Oxide Steel Cup-Point Set-Screw (M5 x 0.8mm, 4mm Length) - 25 Pack', '2806-0005-0004', 'Set-screws play a key role in holding parts in place. The leading edge of this set-screw has a cup-point which provides an excellent hold against a hard surface such as a stainless steel shaft. The added nylon patch on the side becomes compressed when the set-screw is threaded into a part, providing a sure hold that is far less likely to loosen under the stresses and vibrations during usage.', 'goBILDA', null, true, 'https://www.gobilda.com/2806-series-black-oxide-steel-cup-point-set-screw-m5-x-0-8mm-4mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/509/images/14344/2806-0005-0004__28153.1737555318.386.513.jpg?c=1', 'HARDWARE / Screws / M5 Set Screws', 'gobilda'),
  ('2806 Series Black Oxide Steel Cup-Point Set-Screw (M5 x 0.8mm, 5mm Length) - 25 Pack', '2806-0005-0005', 'Set-screws play a key role in holding parts in place. The leading edge of this set-screw has a cup-point which provides an excellent hold against a hard surface such as a stainless steel shaft. The added nylon patch on the side becomes compressed when the set-screw is threaded into a part, providing a sure hold that is far less likely to loosen under the stresses and vibrations during usage.', 'goBILDA', null, true, 'https://www.gobilda.com/2806-series-black-oxide-steel-cup-point-set-screw-m5-x-0-8mm-5mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/511/images/14346/2806-0005-0005__97186.1737555477.386.513.jpg?c=1', 'HARDWARE / Screws / M5 Set Screws', 'gobilda'),
  ('2806 Series Black Oxide Steel Cup-Point Set-Screw (M5 x 0.8mm, 6mm Length) - 25 Pack', '2806-0005-0006', 'Set-screws play a key role in holding parts in place. The leading edge of this set-screw has a cup-point which provides an excellent hold against a hard surface such as a stainless steel shaft. The added nylon patch on the side becomes compressed when the set-screw is threaded into a part, providing a sure hold that is far less likely to loosen under the stresses and vibrations during usage.', 'goBILDA', null, true, 'https://www.gobilda.com/2806-series-black-oxide-steel-cup-point-set-screw-m5-x-0-8mm-6mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/513/images/14345/2806-0005-0006__79287.1737555363.386.513.jpg?c=1', 'HARDWARE / Screws / M5 Set Screws', 'gobilda'),
  ('2806 Series Black Oxide Steel Cup-Point Set-Screw (M5 x 0.8mm, 8mm Length) - 25 Pack', '2806-0005-0008', null, 'goBILDA', null, true, 'https://www.gobilda.com/2806-series-black-oxide-steel-cup-point-set-screw-m5-x-0-8mm-8mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1373/images/6727/2806-0005-0008__56485__38096.1701992946.386.513.jpg?c=1', null, 'gobilda'),
  ('2807 Series Stainless Steel Shim (4mm ID x 7mm OD, 0.25mm Thickness) - 12 Pack', '2807-0407-0250', 'These 0.25mm thick stainless steel shims are intended to provide a small amount of necessary space between components in your assembly. While shims are typically associated with a shaft in a rotating assembly, there are also times where a plate or bracket needs bumped just a smidge from its natural mounting location, and that''s where these come into play. Given the ID is 4mm, they work great on M4 screws.', 'goBILDA', null, true, 'https://www.gobilda.com/2807-series-stainless-steel-shim-4mm-id-x-7mm-od-0-25mm-thickness-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/515/images/3340/2807-0407-0250__69619__80985.1701991867.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
  ('2807 Series Stainless Steel Shim (4mm ID x 7mm OD, 0.50mm Thickness) - 12 Pack', '2807-0407-0500', 'These 0.5mm thick stainless steel shims are intended to provide a small amount of necessary space between components in your assembly. While shims are typically associated with a shaft in a rotating assembly, there are also times where a plate or bracket needs bumped just a smidge from its natural mounting location, and that''s where these come into play. Given the ID is 4mm, they work great on M4 screws.', 'goBILDA', null, true, 'https://www.gobilda.com/2807-series-stainless-steel-shim-4mm-id-x-7mm-od-0-50mm-thickness-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/517/images/3345/2807-0407-0500__10090__74520.1701991869.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
  ('2807 Series Stainless Steel Shim (4mm ID x 7mm OD, 1mm Thickness) - 12 Pack', '2807-0407-1000', 'These 1mm thick stainless shims are intended to provide a small amount of necessary space between components in your assembly. While shims are typically associated with a shaft in a rotating assembly, there are also times where a plate or bracket needs bumped just a smidge from its natural mounting location, and that''s where these come into play. Given the ID is 4mm, they work great on M4 screws.', 'goBILDA', null, true, 'https://www.gobilda.com/2807-series-stainless-steel-shim-4mm-id-x-7mm-od-1mm-thickness-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/519/images/3348/2807-0407-1000__13522__18448.1701991870.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
  ('2807 Series Stainless Steel Shim (6mm ID x 9mm OD, 0.25mm Thickness) - 12 Pack', '2807-0609-0250', 'These 0.25mm thick stainless steel shims are intended to provide a small amount of necessary space between a 6mm bearing, and the next component in your assembly. Since the inner race and outer race of most bearings share the same thickness, there''s potential for an item that extends over the outer race to scrape as it rotates. By adding a shim, that part can rest against the shim and rotate freely without contacting the outer race.', 'goBILDA', null, true, 'https://www.gobilda.com/2807-series-stainless-steel-shim-6mm-id-x-9mm-od-0-25mm-thickness-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/521/images/3353/2807-0609-0250__44206__36452.1701991871.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
