  ('2809 Series Zinc-Plated Steel Split-Lock Washer (4mm ID x 7mm OD) - 25 Pack', '2809-0004-0007', 'Split-lock washers flatten as a screw or nut is tightened, which creates tension between the head and the surface under the washer. This tension prevents the fastener from loosening due to vibration.', 'goBILDA', null, true, 'https://www.gobilda.com/2809-series-zinc-plated-steel-split-lock-washer-4mm-id-x-7mm-od-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/525/images/3369/2809-0004-0007__45727__77535.1701991876.386.513.jpg?c=1', 'HARDWARE / Washers', 'gobilda'),
  ('2810 Series Zinc-Plated Steel External - Tooth Lock Washer (4mm ID x 8mm OD) - 25 Pack', '2810-0004-0008', 'External-tooth lock washers bite into the head of the screw and the surface under the washer in order to prevent loosening due to vibration.', 'goBILDA', null, true, 'https://www.gobilda.com/2810-series-zinc-plated-steel-external-tooth-lock-washer-4mm-id-x-8mm-od-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/527/images/3379/2810-0004-0008__48721__83576.1701991879.386.513.jpg?c=1', 'HARDWARE / Washers', 'gobilda'),
  ('2811 Series Zinc-Plated Steel Hex Nut (M4 x 0.7mm, 7mm Hex) - 25 Pack', '2811-0004-0007', 'Standard hex nuts have a lower profile compared to nylon-insert locknuts and are perfect for use as a jam nut. If your project requires a locking mechanism, consider pairing these with the split-lock washers.', 'goBILDA', null, true, 'https://www.gobilda.com/2811-series-zinc-plated-steel-hex-nut-m4-x-0-7mm-7mm-hex-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/529/images/3388/2811-0004-0007__50076__00155.1701991881.386.513.jpg?c=1', 'HARDWARE / Nuts', 'gobilda'),
  ('M4 x 0.7mm Nylock Nut — 25 Pack', '2812-0004-0007', 'These M4 locknuts have a nylon insert that the threads of a mating screw must form threads in upon insertion. The displaced nylon will continue to hold tension on the screw threads which act as a locking mechanism to prevent the screw from loosening under vibration.', 'goBILDA', null, true, 'https://www.gobilda.com/m4-x-0-7mm-nylock-nut/?sku=2812-0004-0007', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2201/images/12605/2812-0004-0007__44973__94711__84828.1710941328.1280.1280__64956__25865.1720212902.386.513.jpg?c=1', 'HARDWARE / Nuts', 'gobilda'),
  ('M4 x 0.7mm Nylock Nut — 250 Pack', '2812-0004-0007-250pk', 'These M4 locknuts have a nylon insert that the threads of a mating screw must form threads in upon insertion. The displaced nylon will continue to hold tension on the screw threads which act as a locking mechanism to prevent the screw from loosening under vibration.', 'goBILDA', null, true, 'https://www.gobilda.com/m4-x-0-7mm-nylock-nut/?sku=2812-0004-0007-250pk', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2201/images/12605/2812-0004-0007__44973__94711__84828.1710941328.1280.1280__64956__25865.1720212902.386.513.jpg?c=1', 'HARDWARE / Nuts', 'gobilda'),
  ('Zinc-Plated Steel Hex Head Screw (M4 x 0.7mm, 8mm Length) - 25 Pack', '2813-0004-0008', 'This 8mm length M4 Hex Head Screw rocks all kinds of versatile qualities: 2.8mm tall head fits in spaces that socket head screws cannot Hex head profile provides for perfect capture in 7mm hex counterbores (such as those sprinkled throughout the goBILDA® ecosystem) Since hex head screws can be tightened via a wrench from the side, you don''t need any clearance above the head as you do with socket head screws', 'goBILDA', null, true, 'https://www.gobilda.com/zinc-plated-steel-hex-head-screw-m4-x-0-7mm-8mm-length-25-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1871/images/10072/2813-0004-0008__04254__34644.1701993987.386.513.jpg?c=1', 'HARDWARE / Screws / M4 Hex Head Screws', 'gobilda'),
